{
  "assessment": "The source provides a quantitative study of wave-packet dynamics across the Anderson transition on small-world graphs, with two distinct regimes (localized and delocalized) that share controls (K, t) and readouts (Pi(0,t), tau_loc, tau_ergo). The localized regime yields a finite-time scaling law with exponent nu_loc ~ 1.06, and the delocalized regime yields an ergodic time scaling with exponent nu = 0.5. These form a coherent quantitative cluster suitable for authoring.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Weitao Chen, Critical Dynamics of the Anderson Transition on Small-World Graphs, Physical Review Letters (2026), DOI:10.1103/tyrf-2yf7",
    "journal_doi": "10.1103/tyrf-2yf7",
    "arxiv_versioned_id": "2502.16884v1"
  },
  "paper_scope": "The paper studies the critical dynamics of the Anderson transition on small-world graphs using a unitary kicked model (UASW). It focuses on wave-packet dynamics, return probability, localization times, and ergodic time scaling across localized, critical, and delocalized regimes.",
  "mechanisms": [
    {
      "mechanism_id": "localized_finite_time_scaling",
      "statement": "In the localized phase, the return probability Pi(0,t) obeys a finite-time scaling law in ln t / ln tau_loc, where tau_loc is the average localization time that diverges algebraically as ln tau_loc ~ |K - K_c|^{-nu_loc} with nu_loc ~ 1.06.",
      "equations": [
        "(Pi(0,t) - Pi_c(0,inf)) / (Pi_c(0,t) - Pi_c(0,inf)) = F(ln t / ln tau_loc)",
        "ln tau_loc ~ |K - K_c|^{-nu_loc}"
      ],
      "variable_names": ["Pi(0,t)", "Pi_c(0,t)", "Pi_c(0,inf)", "tau_loc", "K", "K_c", "nu_loc"],
      "parameters": [
        {
          "name": "nu_loc_localized",
          "value": 1.06,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "critical exponent for localization time divergence",
          "anchors": [
            {
              "line_start": 261,
              "line_end": 261,
              "support": "Caption states ln tau_loc ~ |K - K_c|^{-nu_loc} with nu_loc ~ 1.06."
            }
          ]
        },
        {
          "name": "K_c_localized",
          "value": 1.95,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "critical kicking strength for p=0.1",
          "anchors": [
            {
              "line_start": 247,
              "line_end": 247,
              "support": "Text states critical point at K_c ~ 1.95 for p=0.1."
            }
          ]
        },
        {
          "name": "A_localized",
          "value": 1.0,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "proportionality constant in ln tau_loc ~ A |K - K_c|^{-nu_loc}",
          "anchors": [
            {
              "line_start": 261,
              "line_end": 261,
              "support": "The relation is stated as proportional, so a constant of proportionality is implied."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 261,
          "line_end": 261,
          "support": "Caption describes finite-time scaling collapse and divergence of ln tau_loc with nu_loc ~ 1.06."
        },
        {
          "line_start": 320,
          "line_end": 320,
          "support": "Text states collapse of data when plotted as ln t / ln tau_loc, revealing ln tau_loc ~ |K - K_c|^{-nu_loc} with nu_loc ~ 1."
        }
      ]
    },
    {
      "mechanism_id": "delocalized_ergodic_time_scaling",
      "statement": "In the delocalized phase, the return probability decays as Pi(0,t) ~ (ln t)^{-d(K)} exp[-(t/tau_ergo)^{beta_d}], and the ergodic time diverges exponentially as tau_ergo(K) ~ exp(cst |K - K_c|^{-nu}) with nu = 0.5.",
      "equations": [
        "Pi(0,t) ~ (ln t)^{-d(K)} exp[-(t/tau_ergo)^{beta_d}]",
        "tau_ergo(K) ~ exp(cst |K - K_c|^{-nu})"
      ],
      "variable_names": ["Pi(0,t)", "d(K)", "tau_ergo", "beta_d", "K", "K_c", "nu"],
      "parameters": [
        {
          "name": "beta_d_delocalized",
          "value": 0.61,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
